/**
 * Pure open/close + selection state for the PR modal (unit-tested without DOM).
 */

function createInitialModalState() {
  return {
    open: false,
    owner: null,
    repo: null,
    number: null,
    layoutMode: 'centered',
    loading: false,
    error: null,
    detail: null,
    files: [],
    virtualRows: [],
    scrollTop: 0,
    viewportHeight: 480,
    rowHeight: 22,
    searchQuery: '',
    searchHits: [],
    searchHitIndex: -1,
    activeFilePath: null,
  };
}

function openModal(state, { owner, repo, number }) {
  return {
    ...state,
    open: true,
    owner,
    repo,
    number,
    layoutMode: 'centered',
    loading: true,
    error: null,
    detail: null,
    files: [],
    virtualRows: [],
    scrollTop: 0,
    searchQuery: '',
    searchHits: [],
    searchHitIndex: -1,
    activeFilePath: null,
  };
}

function closeModal(state) {
  return {
    ...createInitialModalState(),
    // keep measured geometry prefs
    viewportHeight: state.viewportHeight,
    rowHeight: state.rowHeight,
  };
}

function setLayoutMode(state, layoutMode) {
  return { ...state, layoutMode };
}

function setScrollTop(state, scrollTop) {
  return { ...state, scrollTop: Math.max(0, scrollTop) };
}

function setSearchResults(state, query, hits, hitIndex = 0) {
  const list = Array.isArray(hits) ? hits : [];
  const idx =
    list.length === 0 ? -1 : Math.max(0, Math.min(hitIndex, list.length - 1));
  const hit = idx >= 0 ? list[idx] : null;
  return {
    ...state,
    searchQuery: query || '',
    searchHits: list,
    searchHitIndex: idx,
    activeFilePath: hit?.filePath || state.activeFilePath,
  };
}

function selectSearchHit(state, hitIndex) {
  const list = state.searchHits || [];
  if (!list.length) return { ...state, searchHitIndex: -1 };
  const idx = ((hitIndex % list.length) + list.length) % list.length;
  const hit = list[idx];
  return {
    ...state,
    searchHitIndex: idx,
    activeFilePath: hit?.filePath || state.activeFilePath,
  };
}

const api = {
  createInitialModalState,
  openModal,
  closeModal,
  setLayoutMode,
  setScrollTop,
  setSearchResults,
  selectSearchHit,
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = api;
}
if (typeof globalThis !== 'undefined') {
  globalThis.PRModalState = api;
}

